insert into public."posts" ("id", "title", "slug", "excerpt", "content", "cover_image", "tags", "category", "status", "featured", "seo", "published_at", "created_at", "updated_at") values
(1, 'Membangun CMS AI-First dengan Laravel', 'membangun-cms-ai-first-laravel', 'Bagaimana AI mengubah cara kita mengelola konten website. Pelajari cara membangun CMS yang terintegrasi dengan AI assistant.', '## PendahuluannnAI-First CMS adalah pendekatan baru dalam pengelolaan konten website di mana asisten AI menjadi bagian inti dari alur kerja.nn## Kenapa AI-First?nn1. **Efisiensi** Ã¢â‚¬â€ AI membantu menulis dan mengedit konten lebih cepatn2. **Konsistensi** Ã¢â‚¬â€ Gaya tulisan tetap terjagan3. **SEO Otomatis** Ã¢â‚¬â€ Meta title dan description dibuat otomatisnn## KesimpulannnDengan mengintegrasikan OpenRouter AI ke dalam Laravel, pengelolaan konten menjadi jauh lebih mudah dan powerful.', NULL, '["laravel","ai","cms"]', 'Web Development', 'published', true, NULL, '2026-08-03 20:17:32', '2026-08-04 22:40:57', '2026-08-06 20:17:32'),
(2, 'Tips Optimasi Query MySQL untuk Aplikasi Skala Besar', 'tips-optimasi-query-mysql', 'Pelajari teknik index, query caching, dan best practice optimasi database agar aplikasi tetap cepat saat data membesar.', '## IndexingnnIndex memungkinkan database menemukan data dengan cepat. Gunakan index pada kolom yang sering dipakai di WHERE dan JOIN.nn## Query Optimizationnn- Gunakan EXPLAIN untuk menganalisis queryn- Hindari SELECT * dan ambil kolom yang dibutuhkan sajan- Gunakan eager loading di ORMnn## CachingnnCache hasil query yang jarang berubah menggunakan Redis untuk mempercepat response.', NULL, '["mysql","database","performance"]', 'Database', 'published', false, NULL, '2026-07-30 20:17:32', '2026-08-04 22:40:57', '2026-08-06 20:17:32')
insert into public."projects" ("id", "title", "slug", "description", "tech_stack", "category", "thumbnail", "thumbnail_prompt", "github_url", "live_url", "status", "featured", "seo", "tags", "created_at", "updated_at") values
(1, 'Porto CMS Ã¢â‚¬â€ AI Portfolio Platform', 'porto-cms', 'CMS portfolio modern berbasis Laravel dengan AI assistant terintegrasi untuk mengelola hero, projects, blog, SEO, dan theme tanpa coding.', '["Laravel","Tailwind CSS","OpenRouter AI","MySQL"]', 'Web App', NULL, NULL, 'https://github.com/', NULL, 'published', true, NULL, '["cms","laravel","ai"]', '2026-08-04 22:40:57', '2026-08-04 22:40:57'),
(2, 'API E-Commerce dengan Laravel', 'api-ecommerce', 'RESTful API untuk platform e-commerce dengan autentikasi JWT, manajemen produk, keranjang, dan sistem pembayaran.', '["Laravel","MySQL","JWT","REST API"]', 'Backend', NULL, NULL, 'https://github.com/', NULL, 'published', true, NULL, '["api","ecommerce","backend"]', '2026-08-04 22:40:57', '2026-08-04 22:40:57'),
(4, 'Aplikasi MyFilm', 'aplikasi-myfilm', 'Implementasi dari cloud computing menggunakan API menggunakan Android Studio', NULL, 'Mobile App', 'media/projects/Ud9H0TyuVJVfV2DfvPHfVHlg4za8Ld5ZFIiMSGk3.png', NULL, 'https://github.com/Izaswara/MyFilm', NULL, 'published', true, NULL, '["[Android Studio","API]"]', '2026-08-06 18:08:22', '2026-08-06 18:09:25'),
(5, 'Web Kecamatan', 'web-kecamatan', 'Website kecamatan yang menampilkan informasi dari kecamatan yang menggunakan Laravel 10', '["Laravel","js","MySql"]', 'Website', NULL, NULL, 'https://github.com/Izaswara/WEB-UAS-KEC', NULL, 'published', true, NULL, '["Website"]', '2026-08-06 18:11:41', '2026-08-06 18:11:41'),
(6, 'Dashboard Analitik Real-time', 'dashboard-analitik', 'Dashboard analitik untuk memvisualisasikan data penjualan secara real-time dengan grafik interaktif dan laporan otomatis.', '["Vue.js","Laravel","Charts.js","WebSocket"]', 'Dashboard', NULL, NULL, 'https://github.com/', NULL, 'published', false, NULL, '["dashboard","analytics","vue"]', '2026-08-06 19:47:59', '2026-08-06 19:47:59')
insert into public."prompts" ("id", "name", "slug", "prompt_text", "category", "variables", "is_active", "created_at", "updated_at") values
(1, 'Improve Writing', 'improve-writing', 'Please improve the following text to make it more professional, clear, and engaging. Fix any grammar or spelling errors while preserving the original meaning. Return only the improved text.', 'editor', '["text"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(2, 'Generate Project Description', 'generate-project-description', 'Write a compelling project description based on this title and tech stack. Include the problem, solution, and impact. Return as JSON with keys: description, tags.', 'project', '["title","tech_stack"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(3, 'Write Blog Article', 'write-blog-article', 'Write a detailed, well-structured blog article about {topic}. Include an engaging introduction, subheadings, and a conclusion. Return the article in HTML format.', 'blog', '["topic"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(4, 'SEO Meta Tags', 'seo-meta', 'Generate SEO meta tags for {title}. Return JSON with keys: meta_title (max 60 chars), meta_description (max 160 chars), meta_keywords (comma separated), slug.', 'seo', '["title"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(5, 'Generate Experience Description', 'generate-experience', 'Write a professional work experience description for role {title} at {company}. Highlight achievements with measurable results. Return as JSON with keys: description, achievements (array of 3-5 bullets).', 'experience', '["title","company"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(6, 'Generate Skill Description', 'generate-skill', 'Write a short, professional description for the skill "{skill}". Mention where it is commonly used and its value. Max 2 sentences.', 'skill', '["skill"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(7, 'Generate Image Prompt', 'generate-image-prompt', 'Create a detailed AI image generation prompt for: {subject}. Include style, lighting, colors, composition, and mood. Max 100 words, in English.', 'image', '["subject"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(8, 'Translate Text', 'translate-text', 'Translate the following text to {language}. Keep the tone and meaning. Return only the translated text.', 'translation', '["text","language"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(9, 'Summarize Article', 'summarize-article', 'Summarize the following article into {length} concise key points. Return as a JSON array of strings.', 'blog', '["text","length"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(10, 'Generate FAQ', 'generate-faq', 'Generate a list of {count} common questions and answers about: {topic}. Return as JSON array with keys: question, answer.', 'general', '["topic","count"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(11, 'Generate Timeline', 'generate-timeline', 'Generate a career/education timeline from these experiences. Return as JSON array with keys: date, title, description.', 'experience', '["experiences"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(12, 'Resume Summary', 'resume-summary', 'Write a compelling professional summary (max 150 words) for a CV based on these details: {details}.', 'general', '["details"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(13, 'Generate Caption', 'generate-caption', 'Write a catchy social media caption about {topic} with relevant hashtags. Provide 3 options.', 'general', '["topic"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(14, 'Casual Rewrite', 'casual-rewrite', 'Rewrite the following text in a friendly, casual tone while keeping the message clear. Return only the rewritten text.', 'editor', '["text"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(15, 'Formal Rewrite', 'formal-rewrite', 'Rewrite the following text in a professional, formal tone. Return only the rewritten text.', 'editor', '["text"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(16, 'Humanize Text', 'humanize-text', 'Rewrite the following text so it sounds more natural and human, less AI-generated. Return only the rewritten text.', 'editor', '["text"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(17, 'Generate Education Description', 'generate-education', 'Write a professional description for this education entry: {degree} at {institution}. Return as JSON with key: description.', 'education', '["degree","institution"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14'),
(18, 'Certificate Description', 'certificate-description', 'Write a short description for this certificate: {title} from {issuer}. Emphasize the skills gained. Max 2 sentences.', 'certificate', '["title","issuer"]', true, '2026-08-04 21:28:14', '2026-08-04 21:28:14')
